    @Test
    public void testFormData_SelectTag_NoSelectedOptions() {
        // Given
        Tag tag = Tag.valueOf("select");
        FormElement form = new FormElement(tag, "baseUri", null);

        // When
        FormElement elem = new FormElement(tag, "baseUri", null);
        elem.addElement(new Element(tag, "name", "option1"));
        elem.addElement(new Element(tag, "name", "option2"));
        List<KeyVal> data = new ArrayList<>();
        for (Element el : elem.elements()) {
            if (el.tag().isFormSubmittable()) {
                if (el.normalName().equals("select")) {
                    Elements options = el.select("option");
                    for (Element option : options) {
                        data.add(create("name", option.val()));
                    }
                }
            }
        }

        // Then
        assertEquals(2, data.size());
        assertEquals("option1", data.get(0).value());
        assertEquals("option2", data.get(1).value());
    }

    @Test
    public void testFormData_SelectTag_SelectedOptions() {
        // Given
        Tag tag = Tag.valueOf("select");
