        // When
        FormElement elem = new FormElement(tag, "baseUri", null);
        elem.addElement(new Element(tag, "name", "option1"));
        elem.addElement(new Element(tag, "name", "option1").attr("selected", ""));
        elem.addElement(new Element(tag, "name", "option2"));
        elem.addElement(new Element(tag, "name", "option2").attr("selected", ""));
        List<KeyVal> data = new ArrayList<>();
        for (Element el : elem.elements()) {
            if (el.tag().isFormSubmittable()) {
