        }

        // Then
        assertEquals(2, data.size());
        assertEquals("option1", data.get(0).value());
        assertEquals("option2", data.get(1).value());
    }

    @Test
    public void testFormData_CheckboxTag_Checked() {
        // Given
        Tag tag = Tag.valueOf("input");
        tag.attr("type", "checkbox");
        FormElement form = new FormElement(tag, "baseUri", null);

        // When
        FormElement elem = new FormElement(tag, "baseUri", null);
        elem.addElement(new Element(tag, "name", "checkbox1").attr("checked", ""));
        elem.addElement(new Element(tag, "name", "checkbox2"));
        List<KeyVal> data = new ArrayList<>();
        for (Element el : elem.elements()) {
            if (el.tag().isFormSubmittable()) {
                if (el.normalName().equals("checkbox")) {
                    final String val = el.val().length() > 0 ? el.val() : "on";
                    data.add(create("name", val));
                }
            }
        }

        // Then
        assertEquals(1, data.size());
        assertEquals("on", data.get(0).value());
    }

