    @Test
    public void testFormData_NoFormElements() {
        // Given
        Tag tag = Tag.valueOf("div");
        FormElement form = new FormElement(tag, "baseUri", null);

        // When
        FormElement elem = new FormElement(tag, "baseUri", null);
        List<KeyVal> data = new ArrayList<>();
        for (Element el : elem.elements()) {
            if (el.tag().isFormSubmittable()) {
                if (el.normalName().equals("select")) {
                    Elements options = el.select("option");
                    for (Element option : options) {
                        data.add(create("name", option.val()));
                    }
                } else if (el.normalName().equals("checkbox") || el.normalName().equals("radio")) {
                    final String val = el.val().length() > 0 ? el.val() : "on";
                    data.add(create("name", val));
                } else {
                    data.add(create("name", el.val()));
                }
            }
        }

        // Then
        assertEquals(0, data.size());
    }
